insert into public.course select * from jsonb_populate_recordset(null::public.course, $catalogo$[{"id": "0dc9772a-7e50-4498-89b9-7f5928c266b5", "code": "appcc_prerrequisitos", "level": "base", "title": "APPCC y planes de prerrequisitos", "status": "draft", "summary": "Qué es el sistema de autocontrol de tu local, por qué existen los registros que rellenas y qué tienes que hacer cuando un control se sale de lo normal.", "version": 1, "category": "cumplimiento", "cover_url": "/formacion/portadas/appcc.svg", "account_id": null, "created_at": "2026-08-03T18:49:24.687573+00:00", "created_by": null, "legal_basis": "Reglamento (CE) 852/2004, art. 5 · Codex Alimentarius", "is_mandatory": true, "delivery_mode": "folvy_imparte", "reeval_months": 12, "whatsapp_hook": "APPCC suena a papeleo. Hasta que llega la inspección y pregunta por TU registro. Es *formación obligatoria* y te lo quitas en un rato. 📋", "business_types": ["todos"], "estimated_minutes": 25, "recommended_order": 30, "appcc_prerequisite": true, "pass_threshold_pct": 70, "requires_practical": false, "source_recipe_item_id": null, "adopted_from_course_id": null}, {"id": "1a223873-597f-47c3-a76e-de843cf7e8b4", "code": "temperatura_ruta_delivery", "level": "base", "title": "Temperatura y transporte en ruta", "status": "draft", "summary": "Cómo se mantiene la comida caliente, fría y segura desde que sale el pedido hasta que el cliente abre la puerta. El tramo que casi nadie vigila.", "version": 1, "category": "delivery", "cover_url": "/formacion/portadas/temperatura_ruta.jpg", "account_id": null, "created_at": "2026-08-03T23:04:19.791465+00:00", "created_by": null, "legal_basis": "Reglamento (CE) 852/2004, Anexo II Cap. IV (transporte)", "is_mandatory": false, "delivery_mode": "folvy_imparte", "reeval_months": 12, "whatsapp_hook": "La comida sale a 70°C de tu cocina. ¿A cuánto llega al cliente? La cadena de frío no se rompe sola. 🏍️", "business_types": ["dark_kitchen", "delivery", "restaurante"], "estimated_minutes": 15, "recommended_order": 110, "appcc_prerequisite": true, "pass_threshold_pct": 70, "requires_practical": true, "source_recipe_item_id": null, "adopted_from_course_id": null}, {"id": "2a685836-bded-4032-9d61-716934790130", "code": "escandallo_fichas_tecnicas", "level": "base", "title": "El escandallo: por qué la báscula importa", "status": "draft", "summary": "Qué es una ficha técnica, por qué se pesa, qué es la merma y cómo unos gramos de más en cada plato deciden si el negocio gana o pierde dinero.", "version": 1, "category": "cocina", "cover_url": null, "account_id": null, "created_at": "2026-08-04T10:54:51.680388+00:00", "created_by": null, "legal_basis": "Buenas prácticas de gestión de costes", "is_mandatory": false, "delivery_mode": "folvy_imparte", "reeval_months": 24, "whatsapp_hook": "La báscula no es decoración. Cada gramo de más es dinero que se va. ⚖️", "business_types": ["todos"], "estimated_minutes": 20, "recommended_order": 200, "appcc_prerequisite": false, "pass_threshold_pct": 70, "requires_practical": true, "source_recipe_item_id": null, "adopted_from_course_id": null}, {"id": "3b263b28-1d39-4f3a-8a71-2ef729106645", "code": "recepcion_pedidos", "level": "base", "title": "Recepción: la última frontera antes de tu cocina", "status": "draft", "summary": "Cómo se recibe un pedido: qué se comprueba, qué se rechaza y por qué firmar un albarán sin mirar puede costar dinero y seguridad.", "version": 1, "category": "cocina", "cover_url": null, "account_id": null, "created_at": "2026-08-04T18:25:58.552903+00:00", "created_by": null, "legal_basis": "Reglamento (CE) 852/2004 · Reg. (CE) 178/2002 (trazabilidad)", "is_mandatory": false, "delivery_mode": "folvy_imparte", "reeval_months": 24, "whatsapp_hook": "Lo que entra mal a tu cocina sale peor al plato. Tu última frontera. 🚛", "business_types": ["todos"], "estimated_minutes": 20, "recommended_order": 230, "appcc_prerequisite": true, "pass_threshold_pct": 70, "requires_practical": true, "source_recipe_item_id": null, "adopted_from_course_id": null}, {"id": "3dbcba6c-0b77-45f4-9c9c-e20f2aacca5f", "code": "igualdad_acoso", "level": "base", "title": "Igualdad y prevención del acoso en el trabajo", "status": "draft", "summary": "Qué es y qué no es acoso, cómo se actúa cuando ocurre, y qué puedes hacer tú si te pasa a ti o lo ves en un compañero. Obligatorio en toda empresa, sea del tamaño que sea.", "version": 1, "category": "cumplimiento", "cover_url": "/formacion/portadas/igualdad.jpg", "account_id": null, "created_at": "2026-08-03T18:54:16.642238+00:00", "created_by": null, "legal_basis": "LO 3/2007 · RD 901/2020 · LO 10/2022 · RD 1026/2024", "is_mandatory": true, "delivery_mode": "folvy_imparte", "reeval_months": 24, "whatsapp_hook": "Algo que no debería hacer falta explicar, pero la ley dice que sí. Y tiene razón. *Obligatorio para toda la plantilla* — rápido e importante. 🤝", "business_types": ["todos"], "estimated_minutes": 25, "recommended_order": 40, "appcc_prerequisite": false, "pass_threshold_pct": 70, "requires_practical": false, "source_recipe_item_id": null, "adopted_from_course_id": null}, {"id": "440442dd-3450-4794-bb9b-15641aaf60a3", "code": "limpieza_cierre", "level": "base", "title": "Limpieza y cierre: cómo se deja la cocina", "status": "draft", "summary": "Limpiar no es desinfectar, el cierre no es barrer, y cómo dejas la cocina decide cómo empieza el turno de mañana.", "version": 1, "category": "cocina", "cover_url": null, "account_id": null, "created_at": "2026-08-04T18:34:17.364078+00:00", "created_by": null, "legal_basis": "Reglamento (CE) 852/2004, Anexo II Cap. I, II y V", "is_mandatory": false, "delivery_mode": "folvy_imparte", "reeval_months": 24, "whatsapp_hook": "Limpiar no es pasar el trapo. Desinfectar no es echar lejía a ojo. Este curso te enseña la diferencia. 🧹", "business_types": ["todos"], "estimated_minutes": 20, "recommended_order": 250, "appcc_prerequisite": true, "pass_threshold_pct": 70, "requires_practical": true, "source_recipe_item_id": null, "adopted_from_course_id": null}, {"id": "4e206c5a-240d-4a61-839a-a57da917d95e", "code": "inventario_conteo", "level": "base", "title": "El inventario: contar bien o no contar", "status": "draft", "summary": "Por qué se cuenta, cómo se cuenta bien, qué es el conteo a ciegas y por qué un inventario hecho de memoria es peor que no hacerlo.", "version": 1, "category": "cocina", "cover_url": null, "account_id": null, "created_at": "2026-08-04T16:09:46.221642+00:00", "created_by": null, "legal_basis": "Buenas prácticas de gestión de stock", "is_mandatory": false, "delivery_mode": "folvy_imparte", "reeval_months": 24, "whatsapp_hook": "\"Quedan patatas.\" ¿Cuántas? \"Algunas.\" Así no. Aprende a contar bien. 📊", "business_types": ["todos"], "estimated_minutes": 20, "recommended_order": 220, "appcc_prerequisite": false, "pass_threshold_pct": 70, "requires_practical": true, "source_recipe_item_id": null, "adopted_from_course_id": null}, {"id": "5417dd91-aded-4f78-8bef-8126d9f25d4d", "code": "lgtbi_no_discriminacion", "level": "base", "title": "Igualdad y no discriminación de las personas LGTBI", "status": "draft", "summary": "Qué derechos tienen tus compañeros y compañeras LGTBI en el trabajo, qué es discriminación aunque no lo parezca, y cómo se actúa. Obligatorio en empresas de más de 50 personas.", "version": 1, "category": "cumplimiento", "cover_url": "/formacion/portadas/lgtbi.svg", "account_id": null, "created_at": "2026-08-03T18:59:35.195637+00:00", "created_by": null, "legal_basis": "Ley 4/2023, art. 15.1 · RD 1026/2024", "is_mandatory": false, "delivery_mode": "folvy_imparte", "reeval_months": 24, "whatsapp_hook": "Igualdad y respeto en el trabajo. Necesario por ley y por sentido común. 🏳️‍🌈", "business_types": ["todos"], "estimated_minutes": 20, "recommended_order": 50, "appcc_prerequisite": false, "pass_threshold_pct": 70, "requires_practical": false, "source_recipe_item_id": null, "adopted_from_course_id": null}, {"id": "5f288294-b751-4503-8523-733338d285e3", "code": "manipulador_alimentos", "level": "base", "title": "Higiene alimentaria — manipulador de alimentos", "status": "published", "summary": "Lo que tienes que saber y hacer para que nadie enferme por la comida que sale de tu cocina: higiene personal, temperaturas, contaminación cruzada, limpieza, plagas y trazabilidad.", "version": 1, "category": "cumplimiento", "cover_url": "/formacion/portadas/manipulador.svg", "account_id": null, "created_at": "2026-08-03T17:14:12.734377+00:00", "created_by": null, "legal_basis": "RD 109/2010 · Reglamento (CE) 852/2004, Anexo II Cap. XII", "is_mandatory": true, "delivery_mode": "folvy_imparte", "reeval_months": 48, "whatsapp_hook": "Una olla caliente en la encimera \"hasta que se enfríe sola\"… ¿qué puede salir mal? Todo. Este curso es *obligatorio por ley* — y cuando lo hagas entenderás por qué. 🌡️", "business_types": ["todos"], "estimated_minutes": 30, "recommended_order": 10, "appcc_prerequisite": true, "pass_threshold_pct": 70, "requires_practical": false, "source_recipe_item_id": null, "adopted_from_course_id": null}, {"id": "6561caf9-ab63-4309-870b-747b89ca0db4", "code": "primeros_auxilios", "level": "base", "title": "Primeros auxilios básicos en hostelería", "status": "draft", "summary": "Qué hacer en los primeros minutos ante un atragantamiento, una quemadura, un corte o una reacción alérgica grave. No sustituye a la formación práctica en RCP, pero puede salvar una vida mientras llega la ayuda.", "version": 1, "category": "cumplimiento", "cover_url": "/formacion/portadas/primeros_auxilios.svg", "account_id": null, "created_at": "2026-08-03T19:19:38.501891+00:00", "created_by": null, "legal_basis": "Ley 31/1995 (LPRL), art. 20 · Recomendaciones ERC/CERCP", "is_mandatory": false, "delivery_mode": "mixto", "reeval_months": 24, "whatsapp_hook": "Un compañero se corta, se quema o se marea. ¿Sabes qué hacer EN LOS PRIMEROS 2 MINUTOS? 🩹", "business_types": ["todos"], "estimated_minutes": 25, "recommended_order": 80, "appcc_prerequisite": false, "pass_threshold_pct": 70, "requires_practical": false, "source_recipe_item_id": null, "adopted_from_course_id": null}, {"id": "672de77a-2268-4078-9752-7524e1ad07ca", "code": "prl_riesgos_laborales", "level": "base", "title": "Prevención de Riesgos Laborales (PRL)", "status": "draft", "summary": "Formación obligatoria que Folvy NO imparte: la da tu servicio de prevención. Aquí se archiva el certificado, se vigila su caducidad y se demuestra en inspección.", "version": 1, "category": "cumplimiento", "cover_url": "/formacion/portadas/prl.svg", "account_id": null, "created_at": "2026-08-03T19:22:44.941562+00:00", "created_by": null, "legal_basis": "Ley 31/1995 (LPRL), art. 19 · RD 39/1997, Reglamento de los Servicios de Prevención", "is_mandatory": true, "delivery_mode": "solo_archivo", "reeval_months": null, "whatsapp_hook": "Suelos mojados, aceite a 180°, cuchillos afilados. Tu cocina tiene riesgos reales. *Obligatorio por ley* — léelo y firma que lo has hecho. ⚠️", "business_types": ["todos"], "estimated_minutes": 0, "recommended_order": 90, "appcc_prerequisite": false, "pass_threshold_pct": 0, "requires_practical": false, "source_recipe_item_id": null, "adopted_from_course_id": null}, {"id": "67ee220b-f2e3-493d-bb03-d76b357dbefd", "code": "mermas_aprovechamiento", "level": "base", "title": "Mermas: lo que se tira también se ha pagado", "status": "draft", "summary": "Qué es la merma, cuál es inevitable y cuál no, cómo se aprovecha lo que hoy va a la basura, y por qué registrarla es lo que hace que los números signifiquen algo.", "version": 1, "category": "cocina", "cover_url": null, "account_id": null, "created_at": "2026-08-04T15:45:25.483356+00:00", "created_by": null, "legal_basis": "Buenas prácticas de gestión · Ley 1/2025 de prevención del desperdicio alimentario", "is_mandatory": false, "delivery_mode": "folvy_imparte", "reeval_months": 24, "whatsapp_hook": "Lo que tiras también lo has pagado. Cada merma es margen que se evapora. 🗑️", "business_types": ["todos"], "estimated_minutes": 20, "recommended_order": 210, "appcc_prerequisite": false, "pass_threshold_pct": 70, "requires_practical": true, "source_recipe_item_id": null, "adopted_from_course_id": null}, {"id": "7566a927-f925-4a13-9c39-7215d663f606", "code": "estacion_kds", "level": "base", "title": "La estación: pedidos, cocina y disponibilidad", "status": "draft", "summary": "Cómo se usa la tablet del pase: aceptar pedidos, llevar el tablero de cocina y agotar un producto. La herramienta con la que trabajas cada servicio.", "version": 1, "category": "delivery", "cover_url": "/formacion/portadas/estacion_kds.jpg", "account_id": null, "created_at": "2026-08-03T23:16:19.53194+00:00", "created_by": null, "legal_basis": "Manual de operación de Folvy", "is_mandatory": false, "delivery_mode": "folvy_imparte", "reeval_months": 12, "whatsapp_hook": "La tablet pita, hay 6 pedidos y tú mirando la pantalla como si fuera Netflix. Aprende a dominarla. 📱", "business_types": ["dark_kitchen", "delivery", "restaurante"], "estimated_minutes": 15, "recommended_order": 130, "appcc_prerequisite": false, "pass_threshold_pct": 70, "requires_practical": true, "source_recipe_item_id": null, "adopted_from_course_id": null}, {"id": "75a660c4-8b46-47a2-9907-e304cd517d15", "code": "proteccion_datos_rgpd", "level": "base", "title": "Protección de datos (RGPD) en el trabajo", "status": "draft", "summary": "Qué datos manejas sin darte cuenta, qué puedes hacer con ellos y qué no, y qué hacer si se pierde un móvil o alguien pide sus datos. Con lo que dice la AEPD sobre cámaras, WhatsApp y fichaje.", "version": 1, "category": "cumplimiento", "cover_url": "/formacion/portadas/rgpd.svg", "account_id": null, "created_at": "2026-08-03T19:07:27.788132+00:00", "created_by": null, "legal_basis": "RGPD (UE) 2016/679 · LOPDGDD 3/2018 · Guía AEPD relaciones laborales", "is_mandatory": true, "delivery_mode": "folvy_imparte", "reeval_months": 12, "whatsapp_hook": "El teléfono de un cliente no es para tu WhatsApp personal. *Formación obligatoria de protección de datos* — rapidito y cumples. 🔒", "business_types": ["todos"], "estimated_minutes": 25, "recommended_order": 60, "appcc_prerequisite": false, "pass_threshold_pct": 70, "requires_practical": false, "source_recipe_item_id": null, "adopted_from_course_id": null}, {"id": "84a11ff2-b3ba-4930-a731-fa4bf4b56067", "code": "alergenos_intolerancias", "level": "base", "title": "Gestión de alérgenos e intolerancias en hostelería", "status": "published", "summary": "Los 14 alérgenos de declaración obligatoria, cómo evitar la contaminación cruzada y qué contestar cuando un cliente pregunta. Lo que puede salvar una vida en tu turno.", "version": 2, "category": "cumplimiento", "cover_url": "/formacion/portadas/alergenos.svg", "account_id": null, "created_at": "2026-08-03T15:36:54.955822+00:00", "created_by": null, "legal_basis": "Reglamento (UE) 1169/2011 · Real Decreto 126/2015", "is_mandatory": true, "delivery_mode": "folvy_imparte", "reeval_months": 12, "whatsapp_hook": "\"¿Lleva frutos secos?\" — si dudas, este curso es para ti. Porque \"creo que no\" no es una respuesta válida con un alérgico delante. *Obligatorio para todos los que tocan alimentos*. 🥜", "business_types": ["todos"], "estimated_minutes": 25, "recommended_order": 20, "appcc_prerequisite": true, "pass_threshold_pct": 70, "requires_practical": false, "source_recipe_item_id": null, "adopted_from_course_id": null}, {"id": "acd7e015-e8ee-4dc9-911a-85afc504db5e", "code": "conservacion_etiquetado", "level": "base", "title": "Conservación y etiquetado: que dure y que se sepa qué es", "status": "draft", "summary": "Cómo se guarda cada cosa para que aguante, cuánto dura de verdad, y por qué un táper sin etiqueta acaba siempre en la basura.", "version": 1, "category": "cocina", "cover_url": null, "account_id": null, "created_at": "2026-08-04T18:30:17.473144+00:00", "created_by": null, "legal_basis": "Reglamento (CE) 852/2004, Anexo II · Reg. (UE) 1169/2011 (alérgenos)", "is_mandatory": false, "delivery_mode": "folvy_imparte", "reeval_months": 24, "whatsapp_hook": "Esa tarrina sin etiqueta en la cámara… ¿es de ayer o de la semana pasada? Exacto. Haz el curso. 🏷️", "business_types": ["todos"], "estimated_minutes": 20, "recommended_order": 240, "appcc_prerequisite": true, "pass_threshold_pct": 70, "requires_practical": true, "source_recipe_item_id": null, "adopted_from_course_id": null}, {"id": "efd0b8a2-3628-4cc8-979b-19385b270c6e", "code": "embolsado_delivery", "level": "base", "title": "Embolsado y montaje del pedido", "status": "draft", "summary": "Cómo montar un pedido para que llegue caliente, completo y presentable. Es donde se generan casi todas las reclamaciones, y donde más fácil es evitarlas.", "version": 1, "category": "delivery", "cover_url": "/formacion/portadas/embolsado.jpg", "account_id": null, "created_at": "2026-08-03T22:59:11.361279+00:00", "created_by": null, "legal_basis": "Buenas prácticas de operación · Reg. (CE) 852/2004 (transporte de alimentos)", "is_mandatory": false, "delivery_mode": "folvy_imparte", "reeval_months": 12, "whatsapp_hook": "El cliente no ve tu cocina, ve tu bolsa. Si llega mal, da igual lo bien que cocines. 📦", "business_types": ["dark_kitchen", "delivery", "restaurante"], "estimated_minutes": 15, "recommended_order": 100, "appcc_prerequisite": false, "pass_threshold_pct": 70, "requires_practical": true, "source_recipe_item_id": null, "adopted_from_course_id": null}, {"id": "f7dd60e3-3f91-4d7f-b4a3-9244b6d897a1", "code": "canal_denuncias", "level": "base", "title": "Canal interno de información (canal de denuncias)", "status": "draft", "summary": "Qué es el canal, qué se puede comunicar por él, qué protección tienes si lo usas y qué no es (no es para quejarse del cuadrante). Obligatorio en empresas de 50 o más personas.", "version": 1, "category": "cumplimiento", "cover_url": "/formacion/portadas/canal_denuncias.svg", "account_id": null, "created_at": "2026-08-03T19:12:38.17845+00:00", "created_by": null, "legal_basis": "Ley 2/2023 · Directiva (UE) 2019/1937", "is_mandatory": false, "delivery_mode": "folvy_imparte", "reeval_months": 24, "whatsapp_hook": "Si ves algo que no está bien, hay un canal seguro para decirlo. Aquí te explicamos cómo. 📢", "business_types": ["todos"], "estimated_minutes": 20, "recommended_order": 70, "appcc_prerequisite": false, "pass_threshold_pct": 70, "requires_practical": false, "source_recipe_item_id": null, "adopted_from_course_id": null}, {"id": "fb09df4b-faab-40a8-9316-820516114d0c", "code": "incidencias_delivery", "level": "base", "title": "Incidencias en delivery: qué hacer cuando algo se tuerce", "status": "draft", "summary": "Producto agotado, pedido que se retrasa, cliente enfadado, reclamación por algo que faltaba. Qué se hace, en qué orden y quién decide.", "version": 1, "category": "delivery", "cover_url": "/formacion/portadas/incidencias.svg", "account_id": null, "created_at": "2026-08-03T23:09:02.815622+00:00", "created_by": null, "legal_basis": "Buenas prácticas de operación", "is_mandatory": false, "delivery_mode": "folvy_imparte", "reeval_months": 12, "whatsapp_hook": "Pedido equivocado, cliente enfadado, plataforma reclamando. ¿Qué haces? Hay un protocolo y es rápido. 🚨", "business_types": ["dark_kitchen", "delivery", "restaurante"], "estimated_minutes": 15, "recommended_order": 120, "appcc_prerequisite": false, "pass_threshold_pct": 70, "requires_practical": false, "source_recipe_item_id": null, "adopted_from_course_id": null}]$catalogo$::jsonb) on conflict do nothing;

